// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed caller address to ensure generality; the property must hold for any caller
    function testFuzz_property(address caller, address recipient, uint256 amount) public {
        // keep addresses non-zero for meaningful interactions but allow zero as well
        // bound amount to a large but reasonable value (not strictly necessary)
        amount = bound(amount, 0, type(uint256).max);

        // record old proposalCount
        uint256 before = c.proposalCount();

        // call newGrantProposal from fuzzed caller
        vm.prank(caller);
        // call (should always succeed)
        bool ok;
        try c.newGrantProposal(recipient, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, the reference contract always increments proposalCount by 1 (even if caller==0)
        // so the expected relation is: if call succeeded, proposalCount == before + 1
        // We assert the universal property observed from the contract's public getter.
        // Single assertion required by the harness: only assert when call succeeded because if call reverted
        // it's a behavior difference unrelated to the increment (and reference should not revert here).
        if (ok) {
            assertTrue(c.proposalCount() == before + 1);
        } else {
            // If the call reverted, still assert false to force failure on reference if it ever reverts.
            // But per reference behavior the call should not revert; this keeps assertion about public state.
            assertTrue(false);
        }
    }
}

