pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the recipient address and amount; for the property we only need any inputs
    function testFuzz_property(address recipient, uint256 amount) public {
        // Keep recipient wide but avoid zero-address to ensure emitted state stored normally
        // (zero is allowed by contract logic for addresses in other funcs but here it's fine either way)
        // Record prior count
        uint256 before = c.proposalCount();

        // Call newGrantProposal as the fuzzer-specified caller
        vm.prank(address(0xBEEF));
        c.newGrantProposal(recipient, amount);

        uint256 after = c.proposalCount();

        // General rule: reference increments by exactly 1 for ANY inputs; mutant increments by 2 for some inputs.
        // Assert that after == before + 1
        assertTrue(after == before + 1);
    }
}

